import json, os, statistics
from pathlib import Path
import torch
from benchmarks.runners.compare_anthropic_a100 import fixture, capture, elapsed, metadata
@torch.no_grad()
def run(family):
 torch.manual_seed(191)
 model,inputs=fixture(family,768,'miniworld');model=model.cuda().bfloat16().eval()
 for name,p in model.named_parameters():
  if p.ndim>1:p.normal_(std=p.shape[-1]**-.5)
  elif name.endswith('weight'):p.normal_(mean=1,std=.1)
  else:p.normal_(std=.1)
 graphs={};outputs={}
 for label,flag in [('dense','0'),('compact','1')]:
  os.environ['MINIWORLD_TRIATTN_SM80_COMPACT']=flag
  graphs[label],outputs[label]=capture(model,inputs,'miniworld',8)
 error=((outputs['dense'].float()-outputs['compact'].float()).norm()/outputs['dense'].float().norm()).item()
 assert error<.004
 samples={k:[] for k in graphs}
 for i in range(9):
  for key in (list(graphs) if i%2==0 else list(reversed(graphs))):samples[key].append(elapsed(graphs[key],10,8))
 result={'family':family,'length':768,'hardware':metadata(),'relative_difference':error,'samples_ms':samples,
         'times_ms':{k:statistics.median(v) for k,v in samples.items()},
         'speedup':statistics.median(a/b for a,b in zip(samples['dense'],samples['compact'],strict=True))}
 Path(f'/home/psk6950/miniworld-engine-scratch/codex_anthropic_opt/toggle_{family}.json').write_text(json.dumps(result,indent=2,default=str)+'\n')
 print(family,result['times_ms'],result['speedup'],flush=True)
for family in ['triattn','triattn_ending']:run(family)
